// The All About Action emblem, drawn from transparency masks of the supplied logo
// (public/brand/*.png, generated by scripts/build-brand-masks.mjs). The ring and the letterform take
// their colours from the active theme (--ui-logo-border, --ui-logo-glyph); there is no backing
// square unless a theme defines one (--ui-logo-backing).
export default function BrandMark({ size, label }: { size: number; label?: string }) {
  return (
    <span
      className="aaa-brand-mark"
      style={{ width: size, height: size }}
      {...(label ? { role: "img", "aria-label": label } : { "aria-hidden": true })}
    >
      <span className="aaa-brand-ring" />
      <span className="aaa-brand-glyph" />
    </span>
  );
}
